// Generate ui/src/actions.ts from ../actions.json — the one source of the closed Action list
// (desktop.md §Data Model; build.rs generates the Rust side from the same file). Run by
// build.mjs; test/actions.test.mjs fails if the committed file is stale.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));

export function generate() {
  const { actions } = JSON.parse(readFileSync(here("../actions.json"), "utf8"));
  const lines = [
    "// GENERATED by gen-actions.mjs from crates/rein-desktop/actions.json — do not edit.",
    "",
    "export type ActionArg = null | \"n\" | \"name\" | \"style\" | \"dir\";",
    "",
    "export const ACTIONS = [",
    ...actions.map((a) => `  { name: ${JSON.stringify(a.name)}, arg: ${JSON.stringify(a.arg)}, label: ${JSON.stringify(a.label)} },`),
    "] as const satisfies readonly { name: string; arg: ActionArg; label: string }[];",
    "",
    "export type ActionName = (typeof ACTIONS)[number][\"name\"];",
    "",
    "export const ACTION_NAMES: ReadonlySet<string> = new Set(ACTIONS.map((a) => a.name));",
    "",
    "export function isActionName(s: string): s is ActionName {",
    "  return ACTION_NAMES.has(s);",
    "}",
    "",
  ];
  return lines.join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(here("src/actions.ts"), generate());
}
